"use client";
import React, { useState } from "react";
import { 
  ShieldCheck, 
  Watch, 
  Footprints, 
  Shirt, 
  Search, 
  Layers, 
  AlertCircle,
  Cpu
} from "lucide-react";

const qualityData = {
  footwear: [
    { tier: "OG / Retail", level: "Authentic", desc: "Original retail pairs from authorized distribution.", tag: "Genuine" },
    { tier: "Surplus", level: "Authentic", desc: "Excess factory stock. 100% authentic, minor packaging flaws.", tag: "Best Value" },
    { tier: "UA", level: "High-Tier", desc: "Unauthorized Authentic. Same materials, same molds, no brand license.", tag: "Collector Choice" },
    { tier: "10A / God Batch", level: "High-Tier", desc: "Highest replica precision. UV-light perfected.", tag: "1:1" },
    { tier: "7A / Semi UA", level: "Mid-Tier", desc: "Visual 1:1 match, but uses synthetic leather/suede blends.", tag: "Daily Wear" },
    { tier: "5A", level: "Budget", desc: "General silhouette match. Basic materials.", tag: "Economy" },
  ],
  watches: [
    { tier: "Super Clone", level: "High-Tier", desc: "Uses 904L steel and cloned Swiss movements (3135/3235).", tag: "N00B/Clean Factory" },
    { tier: "AAA+ Grade", level: "Mid-Tier", desc: "Automatic Miyota or Seagull movements. Sapphire glass.", tag: "Best Seller" },
    { tier: "Standard Replica", level: "Budget", desc: "Quartz movements. Mineral glass. Lightweight alloy.", tag: "Entry" },
  ],
  apparel: [
    { tier: "Retail / OG", level: "Authentic", desc: "Standard brand-authorized clothing.", tag: "Official" },
    { tier: "High-End Rep", level: "High-Tier", desc: "Correct GSM weight, correct embroidery counts.", tag: "Master" },
    { tier: "General Grade", level: "Budget", desc: "Same print, but lower quality cotton/polyester blends.", tag: "Basic" },
  ]
};

export default function QualityMatrixPage() {
  const [activeTab, setActiveTab] = useState<keyof typeof qualityData>("footwear");

  return (
    <div className="bg-[#050505] text-white min-h-screen pb-20 selection:bg-brand selection:text-black">
      
      {/* 1. FUTURISTIC HERO */}
      <header className="pt-24 pb-16 px-6 max-w-7xl mx-auto border-b border-white/5">
        <div className="flex items-center gap-3 text-brand mb-6">
          <Cpu size={16} className="animate-pulse" />
          <span className="text-[10px] font-black uppercase tracking-[0.8em]">Quality Classification System</span>
        </div>
        <h1 className="text-[12vw] md:text-[8vw] font-black uppercase italic tracking-tighter leading-[0.8] mb-8">
          The <span className="text-brand">Matrix.</span>
        </h1>
        <p className="max-w-2xl text-sm font-medium uppercase opacity-50 leading-relaxed italic">
          We decode the industry. From Swiss-cloned movements to 1:1 sneaker silhouettes, navigate the tiers of the global market with absolute transparency.
        </p>
      </header>

      {/* 2. CATEGORY NAV (Surgical Style) */}
      <nav className="sticky top-0 z-50 bg-[#050505]/80 backdrop-blur-xl border-b border-white/5">
        <div className="max-w-7xl mx-auto flex justify-around">
          {(Object.keys(qualityData) as Array<keyof typeof qualityData>).map((cat) => (
            <button
              key={cat}
              onClick={() => setActiveTab(cat)}
              className={`flex-1 py-8 flex items-center justify-center gap-3 text-[10px] font-black uppercase tracking-[0.3em] transition-all ${
                activeTab === cat ? "text-brand border-b-2 border-brand" : "opacity-30 hover:opacity-100"
              }`}
            >
              {cat === 'footwear' && <Footprints size={14} />}
              {cat === 'watches' && <Watch size={14} />}
              {cat === 'apparel' && <Shirt size={14} />}
              {cat}
            </button>
          ))}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-6 mt-16">
        {/* 3. THE DATA GRID */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-1">
          {qualityData[activeTab].map((item, i) => (
            <div 
              key={i} 
              className="group relative bg-[#0a0a0a] border border-white/5 p-10 hover:bg-brand transition-all duration-700 cursor-crosshair"
            >
              <div className="flex justify-between items-start mb-12">
                <span className="text-[8px] font-black uppercase tracking-[0.3em] border border-white/20 px-3 py-1 rounded-full group-hover:border-black group-hover:text-black">
                  {item.level}
                </span>
                <span className="text-brand group-hover:text-black font-black italic text-xs">
                  #{i + 1}
                </span>
              </div>

              <div className="space-y-4">
                <h3 className="text-3xl font-black uppercase italic tracking-tighter group-hover:text-black transition-colors">
                  {item.tier}
                </h3>
                <p className="text-xs opacity-50 group-hover:text-black group-hover:opacity-80 leading-relaxed font-bold uppercase italic">
                  {item.desc}
                </p>
              </div>

              <div className="mt-12 pt-6 border-t border-white/5 group-hover:border-black/10 flex justify-between items-center">
                <span className="text-[10px] font-black uppercase tracking-widest group-hover:text-black">
                  {item.tag}
                </span>
                <Layers size={16} className="opacity-20 group-hover:text-black group-hover:opacity-100" />
              </div>
            </div>
          ))}
        </div>

        {/* 4. SURPLUS SPOTLIGHT */}
        <div className="mt-24 bg-brand p-12 md:p-24 rounded-[4rem] text-black overflow-hidden relative group">
          <div className="absolute right-0 top-0 p-10 opacity-10 group-hover:rotate-45 transition-transform duration-1000">
            <ShieldCheck size={400} />
          </div>
          <div className="relative z-10 max-w-3xl space-y-8">
            <h2 className="text-6xl md:text-8xl font-black uppercase italic tracking-tighter leading-[0.8]">
              The <br /> Surplus <br /> Protocol.
            </h2>
            <p className="text-lg font-bold uppercase italic leading-tight">
              Surplus is NOT a replica. It is the gold standard of value—original materials, original labor, original quality, simply rejected by retail for logistical reasons.
            </p>
            <div className="flex gap-4">
              <span className="px-6 py-2 bg-black text-white text-[10px] font-black uppercase tracking-widest rounded-full">100% Authentic</span>
              <span className="px-6 py-2 bg-black text-white text-[10px] font-black uppercase tracking-widest rounded-full">Limited Supply</span>
            </div>
          </div>
        </div>
      </main>

      {/* 5. DISCLAIMER */}
      <footer className="mt-20 px-6 max-w-4xl mx-auto text-center">
         <div className="inline-flex items-center gap-3 p-4 border border-white/10 rounded-2xl opacity-40">
           <AlertCircle size={16} />
           <p className="text-[10px] font-bold uppercase tracking-widest">Grading system updated for 2026 market standards</p>
         </div>
      </footer>
    </div>
  );
}